select 
from ${tableName}

    and item_key = #{item.itemKey}
    and title like concat('%', #{item.title}, '%')
    and publish_date like concat(#{item.publishDate}, '%')
    and target_path like concat(#{item.targetPath}, '%')
    and visual_type = #{item.visualType}
